insert into public.tests (id, slug, title, subtitle, test_type, section_scope, focus_domain_id, difficulty, description, sort_order) values ('fece6b85-dae1-5c9e-a839-24d8ddf58b28', 'drill-rw-craft-structure', 'Reading: Craft and Structure', 'Words in context, purpose, cross-text connections', 'drill', 'rw', 'craft_structure', 'mixed', 'A short, mixed-difficulty set focused on vocabulary in context, the purpose of a text or a part of it, and comparisons between paired texts.', 10) on conflict (slug) do nothing;
insert into public.test_parts (id, test_id, part_index, title, section, duration_seconds) values ('c3dc7e7f-0789-5204-a2b6-3496b4fa9eb4', 'fece6b85-dae1-5c9e-a839-24d8ddf58b28', 1, 'Reading: Craft and Structure', 'rw', 600) on conflict (test_id, part_index) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('dd1373e0-9719-5abf-ad0e-082953612ba7', 'c3dc7e7f-0789-5204-a2b6-3496b4fa9eb4', 1, 'craft_structure', 'words_in_context', 'easy', 'mc', 'The engineer''s proposal was praised for its candour: it listed every assumption that might fail and estimated what each failure would cost.', 'As used in the text, what does the word "candour" most nearly mean?', '[{"key":"A","text":"Ambition"},{"key":"B","text":"Frankness"},{"key":"C","text":"Elegance"},{"key":"D","text":"Caution"}]'::jsonb, 'B', null, 'The colon explains the praise by describing a proposal that openly names its own weak points, which is frankness. ''Caution'' describes the subject matter of the list rather than the quality of speech being praised.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('b69761ef-6953-5830-adea-5cacdb2f6094', 'c3dc7e7f-0789-5204-a2b6-3496b4fa9eb4', 2, 'craft_structure', 'text_structure_purpose', 'easy', 'mc', 'Cities plant trees for shade, and shade lowers street temperatures. But young trees provide almost none, and a newly planted street may take fifteen years to cool measurably. Planning that ignores this delay overpromises relief.', 'What is the main purpose of the text?', '[{"key":"A","text":"To explain how trees lower street temperatures"},{"key":"B","text":"To caution that the benefit of tree planting arrives only after a long delay"},{"key":"C","text":"To argue that cities should stop planting street trees"},{"key":"D","text":"To compare young trees with mature trees in several cities"}]'::jsonb, 'B', null, 'The passage grants the benefit and then focuses on the fifteen-year lag and the planning error it causes. Choice C overstates the point; the text criticises the timing of expectations, not the planting itself.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('07a356da-94bc-59cf-a112-47387f901cfc', 'c3dc7e7f-0789-5204-a2b6-3496b4fa9eb4', 3, 'craft_structure', 'words_in_context', 'medium', 'mc', 'Later editors treated the poet''s punctuation as _______, silently replacing her dashes with commas. Manuscript study has since shown the dashes to be systematic and semantic.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"key":"A","text":"incidental"},{"key":"B","text":"unlawful"},{"key":"C","text":"conventional"},{"key":"D","text":"elaborate"}]'::jsonb, 'A', null, 'Editors who silently replace marks must regard them as unimportant, and the following sentence corrects that by showing the dashes carried meaning. ''Conventional'' would suggest the dashes were ordinary, which gives no reason to replace them.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('5265c918-31d4-5ca8-a8d8-8b324d7f5422', 'c3dc7e7f-0789-5204-a2b6-3496b4fa9eb4', 4, 'craft_structure', 'text_structure_purpose', 'medium', 'mc', 'The following is adapted from a novel. Ama arranged the shop window as she did every Monday: the imported tins at eye level, the local soap below them, the sun-faded boxes she could not sell pushed to the back, where they would stay.', 'What is the main effect of the final clause, ''where they would stay''?', '[{"key":"A","text":"It suggests that Ama expects no change in the shop''s fortunes."},{"key":"B","text":"It shows that Ama intends to reorder the boxes soon."},{"key":"C","text":"It reveals that the shop is unusually well stocked."},{"key":"D","text":"It implies that customers prefer local soap to imported tins."}]'::jsonb, 'A', null, 'The clause converts a weekly arrangement into a permanent condition, quietly signalling resignation. Choice B reverses the meaning of ''would stay'', which forecloses rather than promises change.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('44dd7d96-a041-54fe-a1ad-c641f027fdcc', 'c3dc7e7f-0789-5204-a2b6-3496b4fa9eb4', 5, 'craft_structure', 'cross_text_connections', 'medium', 'mc', 'Text 1: The critic argues that translations age faster than originals because each generation''s idea of natural English changes.
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('f4fbeb91-8b1d-552b-a0ed-855bafef8c4e', 'c3dc7e7f-0789-5204-a2b6-3496b4fa9eb4', 6, 'craft_structure', 'words_in_context', 'hard', 'mc', 'The report''s recommendations are _______: they name no agency, no budget line, and no date by which anything must happen.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"key":"A","text":"unenforceable"},{"key":"B","text":"controversial"},{"key":"C","text":"unprecedented"},{"key":"D","text":"expensive"}]'::jsonb, 'A', null, 'The listed absences — no responsible body, no money, no deadline — are precisely what would be needed to compel action, so the recommendations cannot be enforced. ''Controversial'' is unsupported: the text says nothing about disagreement.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('b0fcea1c-a850-5d51-a121-527167d2974f', 'c3dc7e7f-0789-5204-a2b6-3496b4fa9eb4', 7, 'craft_structure', 'cross_text_connections', 'hard', 'mc', 'Text 1: Because gut bacteria differ so much between individuals, the author argues that dietary advice should be personalised rather than universal.
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('55c265e3-641f-59c0-a840-a6d17233c2f9', 'c3dc7e7f-0789-5204-a2b6-3496b4fa9eb4', 8, 'craft_structure', 'text_structure_purpose', 'hard', 'mc', 'Museum labels usually give an object''s date, material, and place of origin. For looted objects, that format performs a quiet trick: ''Benin, 16th century, brass'' locates the work in space and time while leaving out the only date most visitors would find startling, which is the year it arrived in the case.', 'What is the main purpose of the text?', '[{"key":"A","text":"To recommend that museums display more brass objects"},{"key":"B","text":"To show how a standard labelling convention conceals an object''s recent history"},{"key":"C","text":"To question whether the object was made in the sixteenth century"},{"key":"D","text":"To describe how visitors typically move through museum galleries"}]'::jsonb, 'B', null, 'The text sets out the usual label format and then identifies the fact that format omits — the date of acquisition. Choice C misreads the example, which uses the sixteenth-century date as accurate but incomplete.') on conflict (id) do nothing;
